using System;

namespace Aurore.Foundation.Core.Entities;

/// <summary>
/// Base class for entities identified by a <see cref="Guid"/> that is generated by the application (version 7, so ids
/// created later sort later) and that record when they were created and changed.
/// </summary>
public abstract class Entity : IEntity, ITimestamped
{
    /// <inheritdoc />
    public Guid Id { get; init; } = Guid.CreateVersion7();

    /// <inheritdoc />
    public DateTimeOffset CreatedAt { get; init; }

    /// <inheritdoc />
    public DateTimeOffset UpdatedAt { get; set; }
}

/// <summary><see cref="Entity"/> that is marked as deleted instead of removed.</summary>
public abstract class SoftDeletableEntity : Entity, ISoftDeletable
{
    /// <inheritdoc />
    public DateTimeOffset? DeletedAt { get; set; }
}
